static void safeDelete(Path p) throws IOException {
    try {
        Files.delete(p);
    } catch (NoSuchFileException e) {
        // juz nie istnieje - sukces
    } catch (DirectoryNotEmptyException e) {
        try (Stream<Path> dzieci = Files.list(p)) {
            for (Path dziecko : (Iterable<Path>) dzieci::iterator) {
                safeDelete(dziecko);
            }
        }
        Files.delete(p);
    }
}

static class FileMissingException extends Exception { FileMissingException(String m) { super(m); } }
static class FileNotReadableException extends Exception { FileNotReadableException(String m) { super(m); } }
static class EmptyFileException extends Exception { EmptyFileException(String m) { super(m); } }

static void validate(Path p) throws FileMissingException, FileNotReadableException, EmptyFileException, IOException {
    if (!Files.exists(p)) throw new FileMissingException("Brak pliku: " + p);
    if (!Files.isReadable(p)) throw new FileNotReadableException("Brak uprawnien: " + p);
    if (Files.size(p) == 0) throw new EmptyFileException("Pusty plik: " + p);
}

