static class ApplicationFileException extends RuntimeException {
    ApplicationFileException(String m, Throwable cause) { super(m, cause); }
}

static ApplicationFileException translate(IOException e) {
    if (e instanceof NoSuchFileException nsfe) {
        return new ApplicationFileException("Nie znaleziono pliku: " + nsfe.getFile(), e);
    } else if (e instanceof AccessDeniedException ade) {
        return new ApplicationFileException("Brak dostepu do: " + ade.getFile(), e);
    } else if (e instanceof FileAlreadyExistsException faee) {
        return new ApplicationFileException("Plik juz istnieje: " + faee.getFile(), e);
    }
    return new ApplicationFileException("Nieoczekiwany blad pliku", e);
}

